if [ -n "$VN" ]; then
  AD=$(ffprobe -v error -show_entries format=duration -of csv=p=0 "$VN")
  ffmpeg -y -i parts/seg01_raw.mp4 -vf "tpad=stop_mode=clone:stop_duration=60,trim=duration=${AD},setpts=PTS-STARTPTS" -c:v libx264 -pix_fmt yuv420p parts/seg01.mp4
  cp "$VN" parts/aud01$(echo "$VN" | sed "s/.*\.//;s/^/./")
else
  cp parts/seg01_raw.mp4 parts/seg01.mp4
  ffmpeg -y -f lavfi -i anullsrc=r=44100:cl=stereo -t 25.17 parts/aud01.m4a
fi
echo "file parts/seg01.mp4" >> parts/vlist.txt
ADF=$(ls parts/aud01.* | head -1); echo "file $ADF" >> parts/alist.txt

